/**
 * 改造自 shadcn 原装 base-lyra bubble（https://ui.shadcn.com/r/styles/base-lyra/bubble.json，MIT）。
 * 按 #16 改造：丢弃 secondary／tinted（Q5）；muted 悬停的 color-mix 任意值换成令牌类；
 * max-w-[80%] 换成 max-w-4/5；BubbleReactions 的 ring-2 ring-card 写死，不升格为令牌（Q6）；
 * 不导出 bubbleVariants（Q11）。
 * 代码审查（B1）：去掉全部 `dark:` 颜色类，暗色靠令牌自动切换；destructive 改用浅底配对
 * bg-destructive-subtle + text-destructive-subtle-foreground。
 * 动效由 `motion` 属性选预设（ADR 0021）：`Bubble` 渲染 `data-motion`，挂载时入场，缺省 `slide-up`。
 * 用缺省值时放在 Message 里不自己动（`in-data-[slot=message]:transition-none`）：Message 已经带着它入场，
 * 两层都动会叠成两倍位移。显式传了 `motion` 就照传的来。
 */
import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";
import type * as React from "react";

function BubbleGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="bubble-group"
      className={cn("flex min-w-0 flex-col gap-2", className)}
      {...props}
    />
  );
}

const bubbleVariants = cva(
  "group/bubble relative flex w-fit max-w-4/5 min-w-0 flex-col gap-1 group-data-[align=end]/message:self-end data-[align=end]:self-end data-[variant=ghost]:max-w-full",
  {
    variants: {
      variant: {
        default:
          "*:data-[slot=bubble-content]:bg-primary *:data-[slot=bubble-content]:text-primary-foreground [&>[data-slot=bubble-content]:is(button,a):hover]:bg-primary/80",
        muted:
          "*:data-[slot=bubble-content]:bg-muted [&>[data-slot=bubble-content]:is(button,a):hover]:bg-muted-foreground/20",
        outline:
          "*:data-[slot=bubble-content]:border-border *:data-[slot=bubble-content]:bg-background [&>[data-slot=bubble-content]:is(button,a):hover]:bg-muted [&>[data-slot=bubble-content]:is(button,a):hover]:text-foreground",
        ghost:
          "border-none *:data-[slot=bubble-content]:rounded-none *:data-[slot=bubble-content]:bg-transparent *:data-[slot=bubble-content]:p-0 [&>[data-slot=bubble-content]:is(button,a):hover]:bg-muted [&>[data-slot=bubble-content]:is(button,a):hover]:text-foreground",
        destructive:
          "*:data-[slot=bubble-content]:bg-destructive-subtle *:data-[slot=bubble-content]:text-destructive-subtle-foreground [&>[data-slot=bubble-content]:is(button,a):hover]:bg-destructive/20",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

/**
 * 气泡支持的动效预设（ADR 0021）。缺省 `slide-up`；放在 Message 里时由 Message 动。
 * - `slide-up`：挂载时从下方 16px 升起并淡入，220ms。
 * - `fade`：挂载时只淡入，150ms。
 * - `none`：直接出现。
 */
type BubbleMotion = "none" | "fade" | "slide-up";

function Bubble({
  variant = "default",
  align = "start",
  motion,
  className,
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof bubbleVariants> & {
    align?: "start" | "end";
    motion?: BubbleMotion;
  }) {
  const preset = motion ?? "slide-up";
  return (
    <div
      data-slot="bubble"
      data-variant={variant}
      data-align={align}
      data-motion={preset === "none" ? undefined : preset}
      className={cn(
        bubbleVariants({ variant }),
        motion === undefined && "in-data-[slot=message]:transition-none",
        className,
      )}
      {...props}
    />
  );
}

function BubbleContent({ className, render, ...props }: useRender.ComponentProps<"div">) {
  return useRender({
    defaultTagName: "div",
    props: mergeProps<"div">(
      {
        className: cn(
          "w-fit max-w-full min-w-0 overflow-hidden rounded-surface border border-transparent px-2.5 py-2 text-xs leading-relaxed wrap-break-word group-data-[align=end]/bubble:self-end [button]:text-left [button,a]:transition-colors [button,a]:outline-none [button,a]:focus-visible:border-ring [button,a]:focus-visible:ring-1 [button,a]:focus-visible:ring-ring/50",
          className,
        ),
      },
      props,
    ),
    render,
    state: {
      slot: "bubble-content",
    },
  });
}

const bubbleReactionsVariants = cva(
  "absolute z-10 flex w-fit shrink-0 items-center justify-center gap-1 rounded-control bg-muted px-1.5 py-0.5 text-xs ring-2 ring-card has-[button]:p-0",
  {
    variants: {
      side: {
        top: "top-0 -translate-y-3/4",
        bottom: "bottom-0 translate-y-3/4",
      },
      align: {
        start: "left-3",
        end: "right-3",
      },
    },
    defaultVariants: {
      side: "bottom",
      align: "end",
    },
  },
);

function BubbleReactions({
  side = "bottom",
  align = "end",
  className,
  ...props
}: React.ComponentProps<"div"> & {
  align?: "start" | "end";
  side?: "top" | "bottom";
}) {
  return (
    <div
      data-slot="bubble-reactions"
      data-align={align}
      data-side={side}
      className={cn(bubbleReactionsVariants({ side, align }), className)}
      {...props}
    />
  );
}

export { Bubble, BubbleContent, BubbleGroup, type BubbleMotion, BubbleReactions };
